#include <cstdio>

int main() {
    int C, D, T;
    if (scanf("%d %d %d", &C, &D, &T) != 3) return 0;

    // Combustivel necessario para percorrer D km: D / C litros.
    // Cassio ja possui T litros, logo precisa comprar D/C - T litros
    // (nunca menos que zero, pois ele pode ja ter combustivel suficiente).
    double ans = (double)D / (double)C - (double)T;
    if (ans < 0.0) ans = 0.0;

    // Saida com um digito de precisao (arredondamento do valor exato).
    printf("%.1f\n", ans);
    return 0;
}
